 853│             return .failed(reason: "blackboard/inbox persistence failure recorded; refusing merge")
 854│         }
 855│         if let error = board.lastSaveError() {
 856│             return .failed(reason: "blackboard persistence error recorded; refusing merge: \(error)")
 857│         }
