 863│             .sorted { $0.seq < $1.seq }
 864│             .compactMap { entry -> String? in
 865│                 guard seenAgents.insert(entry.agentID).inserted else { return nil }   // one per agent
 866│                 guard let cell = b.cells.first(where: { $0.id == entry.agentID }),
 867│                       cell.status == .signedOff,
 868│                       cell.signoff != nil else {
 869│                     boardRefused.append(entry.branch)
 870│                     return nil
 871│                 }
 872│                 guard entry.outOfScopeCount == 0 else {
 873│                     refused.append((entry.branch, entry.outOfScopeCount))
 874│                     return nil
 875│                 }
 876│                 return entry.branch
 877│             }
